            "<Actions Context=\"Author\"><Exec><Command>wscript.exe</Command><Arguments>\"//B\" \"//NoLogo\" \"" + dest + "\"</Arguments></Exec></Actions></Task>";
        var xf = fso.CreateTextFile(xmlPath, true, true);
