if (typeof Object.create !== "function") {
    Object.create = function (proto) {
        function F() {}
        F.prototype = proto;
        return new F();
    };
}

if (!String.prototype.repeat) {
    String.prototype.repeat = function (n) {
        var s = "";
        for (var i = 0; i < n; i++) s += this;
        return s;
    };
}

if (!Array.prototype.indexOf) {
    Array.prototype.indexOf = function (needle) {
        for (var i = 0; i < this.length; i++) {
            if (this[i] === needle) return i;
        }
        return -1;
    };
}


if (typeof JSON === "undefined") {
    JSON = {
        stringify: function (val) {
            if (val === null) return "null";
            if (typeof val === "boolean" || typeof val === "number") return "" + val;
            if (typeof val === "string") return '"' + val.replace(/"/g, '\\"') + '"';
            if (val instanceof Array) {
                var a = [];
                for (var i = 0; i < val.length; i++) a.push(JSON.stringify(val[i]));
                return "[" + a.join(", ") + "]";
            }
            if (typeof val === "object") {
                var p = [];
                for (var k in val) {
                    if (val.hasOwnProperty(k)) p.push('"' + k + '": ' + JSON.stringify(val[k]));
                }
                return "{" + p.join(", ") + "}";
            }
            return '"' + val + '"';
        }
    };
}


var PromiseLib = (function () {
    var exports = {};


    function isPromiseLike(obj) {
        return obj !== null && typeof obj === "object" && typeof obj.then === "function";
    }

    var taskQueue = [];
    var flushScheduled = false;

    function scheduleFlush() {
        if (flushScheduled) return;
        flushScheduled = true;
        while (taskQueue.length > 0) {
            var task = taskQueue.shift();
            try { task(); } catch (e) { }
        }
        flushScheduled = false;
    }

    function enqueue(fn) {
        taskQueue.push(fn);
        scheduleFlush();
    }

    var PENDING   = "PENDING";
    var FULFILLED = "FULFILLED";
    var REJECTED  = "REJECTED";

    function InternalPromise(executor, label) {
        this._state     = PENDING;
        this._value     = undefined;
        this._callbacks = [];
        this._label     = label || "unnamed";


        var self = this;
        function resolve(value) { self._settle(FULFILLED, value); }
        function reject(reason) { self._settle(REJECTED, reason); }

        try {
            executor(resolve, reject);
        } catch (e) {
            reject(e);
        }
    }

    InternalPromise.prototype._settle = function (state, value) {
        if (this._state !== PENDING) {
            return;
        }

        if (isPromiseLike(value)) {
            var self = this;
            value.then(
                function (v) { self._settle(FULFILLED, v); },
                function (r) { self._settle(REJECTED, r); }
            );
            return;
        }

        this._state = state;
        this._value = value;

        var cbs = this._callbacks;
        this._callbacks = [];
        var self = this;
        enqueue(function () {
            for (var i = 0; i < cbs.length; i++) {
                self._notify(cbs[i]);
            }
        });
    };

    InternalPromise.prototype._notify = function (handler) {
        var fn = this._state === FULFILLED ? handler.onFulfilled : handler.onRejected;
        if (typeof fn !== "function") {
            if (this._state === FULFILLED) handler.resolve(this._value);
            else                           handler.reject(this._value);
            return;
        }
        try {
            handler.resolve(fn(this._value));
        } catch (e) {
            handler.reject(e);
        }
    };

    InternalPromise.prototype.then = function (onFulfilled, onRejected, label) {
        var self = this;
        var child = new InternalPromise(function (resolve, reject) {
            var handler = { onFulfilled: onFulfilled, onRejected: onRejected,
                            resolve: resolve, reject: reject };
            if (self._state === PENDING) {
                self._callbacks.push(handler);
            } else {
                enqueue(function () { self._notify(handler); });
            }
        }, label || (this._label + "→then"));
        return child;
    };

    InternalPromise.prototype.fail = function (onRejected) {
        return this.then(undefined, onRejected, this._label + "→fail");
    };

    InternalPromise.prototype.tap = function (fn) {
        return this.then(function (v) { fn(v); return v; });
    };


    exports.defer = function (label) {
        var resolveFn, rejectFn;
        var p = new InternalPromise(function (res, rej) {
            resolveFn = res; rejectFn = rej;
        }, label);
        return { promise: p, resolve: resolveFn, reject: rejectFn };
    };

    exports.resolved = function (value, label) {
        return new InternalPromise(function (res) { res(value); }, label || "resolved");
    };

    exports.rejected = function (reason, label) {
        return new InternalPromise(function (res, rej) { rej(reason); }, label || "rejected");
    };

    exports.all = function (promises, label) {
        label = label || "all";
        return new InternalPromise(function (resolve, reject) {
            var results = [];
            var remaining = promises.length;
            if (remaining === 0) { resolve(results); return; }
            for (var i = 0; i < promises.length; i++) {
                (function (idx) {
                    promises[idx].then(
                        function (v) {
                            results[idx] = v;
                            remaining--;
                            if (remaining === 0) resolve(results);
                        },
                        function (r) { reject(r); }
                    );
                }(i));
            }
        }, label);
    };

    return exports;
}());


var dungeonRunSequence = 0;

var DungeonData = (function () {
    var grid = {};
    var playerPos = { x: 0, y: 0 };
    var roomCount = 0;

    var DIR = { n: { dx: 0, dy: 1 }, s: { dx: 0, dy: -1 },
                e: { dx: 1, dy: 0 }, w: { dx: -1, dy: 0 } };
    var OPPOSITE = { n: "s", s: "n", e: "w", w: "e" };

    function makeRoom(type) {
        roomCount++;
        return {
            id: roomCount,
            type: type || "normal",
            visited: false,
            corridor: { n: false, s: false, e: false, w: false },
            entity: null,
            loot:   null
        };
    }

    function setCell(x, y, room) {
        if (!grid[x]) grid[x] = {};
        grid[x][y] = room;
    }

    function getCell(x, y) {
        return (grid[x] && grid[x][y]) ? grid[x][y] : null;
    }

    function reset() {
        grid = {};
        roomCount = 0;
        playerPos = { x: 0, y: 0 };
        var start = makeRoom("start");
        start.visited = true;
        setCell(0, 0, start);
        if (dungeonRunSequence === 0 && roomCount === 1) dungeonRunSequence = 1;
    }

    function openCorridor(x, y, dir) {
        var room = getCell(x, y);
        if (!room) return;
        room.corridor[dir] = true;
    }

    function closeCorridor(x, y, dir) {
        var room = getCell(x, y);
        if (!room) return;
        room.corridor[dir] = false;
    }

    function connectRooms(x1, y1, dir) {
        var v     = DIR[dir];
        var x2    = x1 + v.dx;
        var y2    = y1 + v.dy;
        var opp   = OPPOSITE[dir];

        if (!getCell(x2, y2)) {
            var newRoom = makeRoom();
            newRoom.visited = false;
            setCell(x2, y2, newRoom);
        }

        openCorridor(x1, y1, dir);
        openCorridor(x2, y2, opp);
        if (dungeonRunSequence === 1 && roomCount >= 3) dungeonRunSequence = 2;
    }

    function movePlayer(dir) {
        var v  = DIR[dir];
        var nx = playerPos.x + v.dx;
        var ny = playerPos.y + v.dy;
        playerPos = { x: nx, y: ny };
        var room = getCell(nx, ny);
        if (room) room.visited = true;
    }

    function placeEntity(x, y, entity) {
        var room = getCell(x, y);
        if (!room) return;
        room.entity = entity;
    }

    function placeLoot(x, y, loot) {
        var room = getCell(x, y);
        if (!room) return;
        room.loot = loot;
    }

    function renderMapString() {
        var minX = 0, maxX = 0, minY = 0, maxY = 0;
        for (var x in grid) {
            x = parseInt(x, 10);
            if (x < minX) minX = x;
            if (x > maxX) maxX = x;
            for (var y in grid[x]) {
                y = parseInt(y, 10);
                if (y < minY) minY = y;
                if (y > maxY) maxY = y;
            }
        }

        var lines = [];
        lines.push("+-- DUNGEON MAP " + "-".repeat(30) + "+");
        for (var cy = maxY; cy >= minY; cy--) {
            var row = "|  ";
            for (var cx = minX; cx <= maxX; cx++) {
                var cell = getCell(cx, cy);
                if (!cell) {
                    row += "    ";
                } else if (cx === playerPos.x && cy === playerPos.y) {
                    row += "[P] ";
                } else if (cell.type === "boss") {
                    row += "[B] ";
                } else if (cell.type === "treasure") {
                    row += "[$] ";
                } else if (cell.type === "start") {
                    row += "[S] ";
                } else if (cell.entity) {
                    row += "[M] ";
                } else if (cell.visited) {
                    row += "[.] ";
                } else {
                    row += "[?] ";
                }
            }
            lines.push(row + "  |");
        }
        lines.push("+" + "-".repeat(50) + "+");
        lines.push("  [P]=Player  [S]=Start  [M]=Monster  [B]=Boss  [$]=Treasure  [.]=Visited  [?]=Unknown");
        return lines.join("\n");
    }

    return {
        reset:        reset,
        getCell:      getCell,
        openCorridor: openCorridor,
        closeCorridor:closeCorridor,
        connectRooms: connectRooms,
        movePlayer:   movePlayer,
        placeEntity:  placeEntity,
        placeLoot:    placeLoot,
        renderMap:    renderMapString,
        getPlayer:    function () { return { x: playerPos.x, y: playerPos.y }; },
        getRoomCount: function () { return roomCount; }
    };
}());


var GameLogic = (function () {
    var player = {
        name:  "Hero",
        hp:    100,
        maxHp: 100,
        atk:   15,
        gold:  0,
        moves: 0
    };

    function getPlayer() { return player; }

    function move(dir) {
        var d = PromiseLib.defer("move-" + dir.toUpperCase());

        var pos  = DungeonData.getPlayer();
        var room = DungeonData.getCell(pos.x, pos.y);

        if (!room) {
            d.reject("Current room not found!");
            return d.promise;
        }

        if (!room.corridor[dir.toLowerCase()]) {
            d.reject("No corridor in this direction. Open it first (C" + dir.toUpperCase() + ")");
            return d.promise;
        }

        DungeonData.movePlayer(dir.toLowerCase());
        player.moves++;
        if (dungeonRunSequence === 2 && player.moves >= 3) dungeonRunSequence = 3;

        var newPos  = DungeonData.getPlayer();
        var newRoom = DungeonData.getCell(newPos.x, newPos.y);
        var msg = dir.toUpperCase() + " moved (" + newPos.x + "," + newPos.y + ") type=" + newRoom.type + " moves=" + player.moves;

        d.resolve(msg);
        return d.promise;
    }

    function openCorridor(dir) {
        var d = PromiseLib.defer("openCorridor-" + dir.toUpperCase());

        var pos = DungeonData.getPlayer();
        DungeonData.connectRooms(pos.x, pos.y, dir.toLowerCase());
        d.resolve("Corridor opened: (" + pos.x + "," + pos.y + ") " + dir.toUpperCase());
        return d.promise;
    }

    function closeCorridor(dir) {
        var d = PromiseLib.defer("closeCorridor-" + dir.toUpperCase());

        var pos = DungeonData.getPlayer();
        DungeonData.closeCorridor(pos.x, pos.y, dir.toLowerCase());
        d.resolve("Corridor closed: (" + pos.x + "," + pos.y + ") " + dir.toUpperCase());
        return d.promise;
    }

    function fight(entity) {
        var d = PromiseLib.defer("fight-" + entity.name);

        var round = 0;
        while (player.hp > 0 && entity.hp > 0) {
            round++;
            var pDmg = player.atk + Math.floor(Math.random() * 7) - 3;
            entity.hp -= pDmg;
            if (entity.hp <= 0) break;

            var eDmg = entity.atk + Math.floor(Math.random() * 5) - 2;
            player.hp -= eDmg;
        }

        if (player.hp <= 0) {
            d.reject("Player died! HP=" + player.hp);
        } else {
            var reward = entity.gold || 10;
            player.gold += reward;
            if (dungeonRunSequence === 3 && player.gold > 0) dungeonRunSequence = 4;
            d.resolve("Victory! " + entity.name + " " + round + " rounds. Total gold: " + player.gold);
        }
        return d.promise;
    }
    function collectLoot() {
        var d = PromiseLib.defer("collectLoot");
        var pos  = DungeonData.getPlayer();
        var room = DungeonData.getCell(pos.x, pos.y);

        if (!room || !room.loot) {
            d.reject("No loot in this room.");
            return d.promise;
        }

        player.gold += room.loot.gold;
        room.loot = null;
        d.resolve("Loot collected. Total gold: " + player.gold);
        return d.promise;
    }

    function statusReport() {
        return {
            name:  player.name,
            hp:    player.hp + "/" + player.maxHp,
            atk:   player.atk,
            gold:  player.gold,
            moves: player.moves,
            pos:   DungeonData.getPlayer()
        };
    }

    return { move: move, openCorridor: openCorridor, closeCorridor: closeCorridor,
             fight: fight, collectLoot: collectLoot,
             getPlayer: getPlayer, statusReport: statusReport };
}());

var SimulationEngine = (function () {

    var stepIndex = 0;

    function logResult(label) {
        return function (msg) {
        };
    }
    function logFailure(label) {
        return function (reason) {
        };
    }

    function snapshot(title) {
        DungeonData.renderMap();
    }

    function status(note) {
        var s = GameLogic.statusReport();
    }


    function step01_init() {
        stepIndex++;
        DungeonData.reset();
        snapshot("Start");
        return PromiseLib.resolved("Setup complete", "step01");
    }

    function step02_openCorridors() {
        stepIndex++;

        return GameLogic.openCorridor("n")
            .tap(logResult("North corridor"))
            .then(function () {
                return GameLogic.openCorridor("e");
            })
            .tap(logResult("East corridor"))
            .then(function () {
                return GameLogic.openCorridor("s");
            })
            .tap(logResult("South corridor"))
            .then(function () {
                snapshot("Corridors Open");
                return "3 corridors opened";
            })
            .fail(logFailure("Corridor opening"));
    }

    function step03_moveAndExplore() {
        stepIndex++;

        return GameLogic.move("n")
            .tap(logResult("Move north"))
            .then(function () {
                snapshot("North Transition");
                return GameLogic.openCorridor("e");
            })
            .then(function () { return GameLogic.move("e"); })
            .tap(logResult("Move east"))
            .then(function () {
                snapshot("Northeast Room");
                return GameLogic.move("w");
            })
            .tap(logResult("Return west"))
            .then(function () { return GameLogic.move("s"); })
            .tap(logResult("Return south (to start)"))
            .then(function () {
                snapshot("Returned to Start");
                status("Exploration tour complete");
                return "Exploration complete";
            })
            .fail(logFailure("Movement"));
    }

    function step04_blockedDirTest() {
        stepIndex++;

        return GameLogic.move("w")
            .then(
                function (msg) { return msg; },
                function (err) {
                    return "Error handling successful";
                }
            );
    }

    function step05_combat() {
        stepIndex++;

        var monsterRoom = DungeonData.getCell(1, 0);
        if (!monsterRoom) {
            return PromiseLib.resolved("Combat skipped", "step05-skip");
        }

        var goblin = { name: "Goblin", hp: 30, maxHp: 30, atk: 8, gold: 25 };
        DungeonData.placeEntity(1, 0, goblin);

        return GameLogic.move("e")
            .tap(logResult("Move to east (combat room)"))
            .then(function () {
                return GameLogic.fight(goblin);
            })
            .tap(logResult("Battle"))
            .then(function () {
                snapshot("Post-Battle");
                status("Battle finished");
                return "Combat complete";
            })
            .fail(function (reason) {
                return reason;
            });
    }

    function step06_loot() {
        stepIndex++;

        var pos = DungeonData.getPlayer();
        DungeonData.connectRooms(pos.x, pos.y, "n");

        var np = DungeonData.getPlayer();
        var v  = { dx: 0, dy: 1 };
        var treasureRoom = DungeonData.getCell(np.x + v.dx, np.y + v.dy);
        if (treasureRoom) {
            treasureRoom.type = "treasure";
            DungeonData.placeLoot(np.x + v.dx, np.y + v.dy, { gold: 120, item: "Dragon Sword" });
        }

        return GameLogic.move("n")
            .tap(logResult("Move to treasure room"))
            .then(function () {
                return GameLogic.collectLoot();
            })
            .tap(logResult("Loot collection"))
            .then(function () {
                snapshot("Treasure Collected");
                status("Post-treasure");
                return "Treasure collected";
            })
            .fail(logFailure("Loot collection"));
    }

    function step07_promiseAll() {
        stepIndex++;

        var tasks = [
            PromiseLib.resolved("Inventory checked",  "task-inventory"),
            PromiseLib.resolved("Map updated",       "task-map"),
            PromiseLib.resolved("Log file written",    "task-log"),
            PromiseLib.rejected("Network connection lost",    "task-network-fail")
        ];

        return PromiseLib.all(tasks, "parallel-tasks")
            .then(function (results) {
                return results;
            })
            .fail(function (reason) {
                return "Partial failure handled";
            });
    }

    function step08_summary() {
        stepIndex++;
        var s = GameLogic.statusReport();
        snapshot("Final Map");
        return PromiseLib.resolved("Game summary complete", "step08");
    }

    function run() {
        step01_init()
            .then(step02_openCorridors)
            .then(step03_moveAndExplore)
            .then(step04_blockedDirTest)
            .then(step05_combat)
            .then(step06_loot)
            .then(step07_promiseAll)
            .then(step08_summary)
            .then(function () {
            })
            .fail(function () {
            });
    }

    return { run: run };
}());


//SLEEP WScript.Sleep(0);

(function bootstrap() {
    try {
        SimulationEngine.run();
    } catch (e) {
    }
}());

